import base64
import io
import json
import re
from datetime import datetime, date

import openpyxl


archivo_raw = input.get("file")
archivo_nombre = input.get("filename") or "archivo.xlsx"


def convertir_bytes(valor, vistos=None):
    if vistos is None:
        vistos = set()
    if valor is None:
        return None
    if isinstance(valor, bytes):
        return valor
    if isinstance(valor, bytearray):
        return bytes(valor)
    if isinstance(valor, (list, tuple)):
        if valor and all(isinstance(x, int) and 0 <= x <= 255 for x in valor):
            return bytes(valor)
        for elemento in valor:
            convertido = convertir_bytes(elemento, vistos)
            if convertido:
                return convertido
        return None
    identificador = id(valor)
    if identificador in vistos:
        return None
    vistos.add(identificador)
    if isinstance(valor, dict):
        for elemento in valor.values():
            convertido = convertir_bytes(elemento, vistos)
            if convertido:
                return convertido
        return None
    for metodo in ("to_bytes", "read"):
        try:
            resultado = getattr(valor, metodo)()
            convertido = convertir_bytes(resultado, vistos)
            if convertido:
                return convertido
        except Exception:
            pass
    for atributo in ("data", "buffer", "value", "content", "body"):
        try:
            convertido = convertir_bytes(getattr(valor, atributo), vistos)
            if convertido:
                return convertido
        except Exception:
            pass
    texto = str(valor).strip()
    representaciones = [texto]
    try:
        representaciones.append(repr(valor))
    except Exception:
        pass
    for representacion in representaciones:
        match = re.search(r"IMTBuffer\([^)]*\):\s*([0-9a-fA-F]+)", representacion)
        if match:
            hexadecimal = match.group(1)
            if len(hexadecimal) % 2 == 0:
                return bytes.fromhex(hexadecimal)
        compacto = re.sub(r"\s+", "", representacion)
        if compacto.startswith("UEsDB"):
            try:
                return base64.b64decode(compacto)
            except Exception:
                pass
    return None


def convertir_valor(valor, celda=None):
    if valor is None:
        return None
    if isinstance(valor, (datetime, date)):
        return valor.strftime("%d/%m/%Y")
    if isinstance(valor, str):
        return valor.strip()
    if isinstance(valor, float) and valor.is_integer():
        return int(valor)
    return valor


def texto_seguro(valor):
    if valor is None:
        return ""
    return str(valor).strip()


contenido = convertir_bytes(archivo_raw)
if not contenido:
    raise Exception("No se pudo obtener contenido binario del archivo desde Google Drive.")
if contenido[:2] != b"PK":
    raise Exception("El archivo recibido no es un XLSX válido.")

workbook = openpyxl.load_workbook(io.BytesIO(contenido), data_only=True)
resultado = {
    "archivo": archivo_nombre,
    "hojas": [],
    "instrucciones": "Analizar todas las hojas y todas las filas. Los encabezados pueden estar en cualquier fila; no asumir que la primera fila es el encabezado.",
    "observaciones": []
}

palabras_seccion = (
    "saldo", "balance", "movimiento", "transaccion", "transacción", "resumen",
    "cuenta", "fecha", "credito", "crédito", "debito", "débito", "total",
    "estado de cuenta", "detalle"
)

for nombre_hoja in workbook.sheetnames:
    hoja = workbook[nombre_hoja]
    detalle = {
        "nombre": nombre_hoja,
        "filas": [],
        "secciones_detectadas": [],
        "texto_completo": ""
    }
    texto_filas = []

    for numero_fila in range(1, hoja.max_row + 1):
        valores = []
        celdas = {}
        no_vacios = []

        for numero_columna in range(1, hoja.max_column + 1):
            celda = hoja.cell(numero_fila, numero_columna)
            valor = convertir_valor(celda.value, celda)
            valores.append(valor)
            if valor is not None and str(valor).strip() != "":
                letra = openpyxl.utils.get_column_letter(numero_columna)
                celdas[letra] = valor
                no_vacios.append(str(valor).strip())

        if not no_vacios:
            continue

        texto_fila = " | ".join(no_vacios)
        texto_filas.append(f"Fila {numero_fila}: {texto_fila}")

        fila_info = {
            "fila": numero_fila,
            "valores": valores,
            "celdas": celdas,
            "texto": texto_fila
        }
        detalle["filas"].append(fila_info)

        texto_normalizado = texto_fila.lower()
        if any(palabra in texto_normalizado for palabra in palabras_seccion):
            detalle["secciones_detectadas"].append({
                "fila": numero_fila,
                "texto": texto_fila
            })

    detalle["texto_completo"] = "\n".join(texto_filas)
    resultado["hojas"].append(detalle)

if not resultado["hojas"]:
    resultado["observaciones"].append("El archivo no contiene hojas con datos.")

return {"resultado": json.dumps(resultado, ensure_ascii=False, default=str)}

