import base64
import io
import json
import re
import unicodedata
from copy import copy

from openpyxl import load_workbook
from openpyxl.cell.cell import MergedCell
from openpyxl.styles import Font, PatternFill, Border, Side, Alignment


def normalizar(valor):
    texto = "" if valor is None else str(valor)
    texto = unicodedata.normalize("NFKD", texto).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"[^a-z0-9]+", "", texto.lower())


def obtener(registro, *claves, default=None):
    if not isinstance(registro, dict):
        return default
    normalizados = {normalizar(k): v for k, v in registro.items()}
    for clave in claves:
        buscada = normalizar(clave)
        if buscada in normalizados:
            return normalizados[buscada]
    return default


def convertir_a_bytes(valor, vistos=None):
    if vistos is None:
        vistos = set()
    if valor is None:
        return None
    if isinstance(valor, bytes):
        return valor
    if isinstance(valor, bytearray):
        return bytes(valor)
    if isinstance(valor, (list, tuple)):
        if valor and all(isinstance(x, int) and 0 <= x <= 255 for x in valor):
            return bytes(valor)
        for elemento in valor:
            resultado = convertir_a_bytes(elemento, vistos)
            if resultado:
                return resultado
        return None
    identificador = id(valor)
    if identificador in vistos:
        return None
    vistos.add(identificador)
    if isinstance(valor, dict):
        for elemento in valor.values():
            resultado = convertir_a_bytes(elemento, vistos)
            if resultado:
                return resultado
        return None
    for atributo in ("data", "buffer", "value", "content", "body"):
        try:
            resultado = convertir_a_bytes(getattr(valor, atributo), vistos)
            if resultado:
                return resultado
        except Exception:
            pass
    texto = str(valor).strip()
    match = re.search(r"IMTBuffer\([^)]*\):\s*([0-9a-fA-F]+)", texto)
    if match and len(match.group(1)) % 2 == 0:
        return bytes.fromhex(match.group(1))
    compacto = re.sub(r"\s+", "", texto)
    if compacto.startswith("UEsDB"):
        try:
            return base64.b64decode(compacto)
        except Exception:
            pass
    return None


def editable(hoja, fila, columna):
    celda = hoja.cell(fila, columna)
    return None if isinstance(celda, MergedCell) else celda


def escribir(hoja, fila, columna, valor):
    celda = editable(hoja, fila, columna)
    if celda is not None:
        if isinstance(valor, (dict, list, tuple)):
            valor = json.dumps(valor, ensure_ascii=False)
        celda.value = valor
        return True
    return False


def fila_con_texto(hoja, textos, desde=1):
    buscados = [normalizar(texto) for texto in textos]
    for fila in range(desde, hoja.max_row + 1):
        valores = [normalizar(hoja.cell(fila, columna).value) for columna in range(1, hoja.max_column + 1)]
        if all(any(buscado in valor for valor in valores) for buscado in buscados):
            return fila
    return None


def fila_seccion(hoja, nombres, despues_de=1):
    candidatos = [normalizar(nombre) for nombre in nombres]
    for fila in range(max(1, despues_de), hoja.max_row + 1):
        texto = " ".join(normalizar(hoja.cell(fila, columna).value) for columna in range(1, hoja.max_column + 1))
        if any(candidato in texto for candidato in candidatos):
            return fila
    return None


def copiar_estilo_fila(hoja, origen, destino):
    for columna in range(1, hoja.max_column + 1):
        origen_celda = editable(hoja, origen, columna)
        destino_celda = editable(hoja, destino, columna)
        if origen_celda is None or destino_celda is None:
            continue
        if origen_celda.has_style:
            destino_celda._style = copy(origen_celda._style)
        destino_celda.number_format = origen_celda.number_format


def encabezados_nueva(hoja, fila, valores):
    for columna, valor in enumerate(valores, 1):
        celda = editable(hoja, fila, columna)
        if celda is None:
            continue
        celda.value = valor
        celda.font = Font(bold=True, color="FFFFFF")
        celda.fill = PatternFill(fill_type="solid", fgColor="1A365D")
        celda.border = Border(left=Side(style="thin"), right=Side(style="thin"), top=Side(style="thin"), bottom=Side(style="thin"))
        celda.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)


openai_result = input.get("openai_result")
plantilla_excel = input.get("plantilla_excel")
if not openai_result:
    raise Exception("No se recibió información de OpenAI.")
if not plantilla_excel:
    raise Exception("No se recibió la plantilla Excel.")

if isinstance(openai_result, str):
    texto = openai_result.replace("```json", "").replace("```", "").strip()
    try:
        data = json.loads(texto)
    except Exception as error:
        raise Exception(f"La respuesta de OpenAI no es JSON válido: {error}")
else:
    data = openai_result

if not isinstance(data, dict):
    raise Exception("La respuesta de OpenAI debe ser un objeto JSON.")
for clave in ("bancos_procesados", "resumen_general", "balance_general", "observaciones"):
    if not isinstance(data.get(clave), list):
        data[clave] = []

plantilla_bytes = convertir_a_bytes(plantilla_excel)
if not plantilla_bytes or plantilla_bytes[:2] != b"PK":
    raise Exception("La plantilla recibida no es un XLSX válido.")
wb = load_workbook(io.BytesIO(plantilla_bytes))


def buscar_hoja_banco(nombre_banco):
    nombre = normalizar(nombre_banco)
    grupos = []
    if "industrial" in nombre or nombre.startswith("bi"):
        grupos = ["bi", "industrial"]
    elif "gyt" in nombre:
        grupos = ["gyt"]
    elif "bac" in nombre:
        grupos = ["bac"]
    elif "banrural" in nombre or nombre.startswith("ban"):
        grupos = ["ban", "banrural"]
    for nombre_hoja in wb.sheetnames:
        if any(grupo in normalizar(nombre_hoja) for grupo in grupos):
            return wb[nombre_hoja], False
    nombre_nuevo = str(nombre_banco or "Banco")[:31]
    if nombre_nuevo in wb.sheetnames:
        return wb[nombre_nuevo], False
    return wb.create_sheet(nombre_nuevo), True


def escribir_control(hoja, banco):
    campos = {
        "banco": obtener(banco, "Banco"),
        "cuenta": obtener(banco, "Cuenta"),
        "moneda": obtener(banco, "Moneda"),
        "fechainicial": obtener(banco, "Fecha_Inicial", "Fecha Inicial"),
        "fechafinal": obtener(banco, "Fecha_Final", "Fecha Final"),
        "saldoinicial": obtener(banco, "Saldo_Inicial", "Saldo Inicial"),
        "totalingresos": obtener(banco, "Total_Ingresos", "Total Ingresos"),
        "totalegresos": obtener(banco, "Total_Egresos", "Total Egresos"),
        "saldofinal": obtener(banco, "Saldo_Final", "Saldo Final"),
        "estadoconciliacion": obtener(banco, "Estado_Conciliacion", "Estado Conciliacion")
    }
    for fila in range(1, hoja.max_row + 1):
        for columna in range(1, hoja.max_column + 1):
            etiqueta = normalizar(hoja.cell(fila, columna).value)
            for clave, valor in campos.items():
                if etiqueta == clave or (clave in etiqueta and len(etiqueta) < len(clave) + 10):
                    escribir(hoja, fila, columna + 1, valor)
                    break


ws = wb["Consolidado General"] if "Consolidado General" in wb.sheetnames else wb.create_sheet("Consolidado General", 0)
encabezados_resumen = ["Banco", "Cuenta", "Moneda", "Fecha Inicial", "Fecha Final", "Saldo Inicial", "Total Ingresos", "Total Egresos", "Saldo Final"]
header_resumen = fila_con_texto(ws, ["Banco", "Cuenta"], 1) or 5
if not fila_con_texto(ws, ["Banco", "Cuenta"], 1):
    encabezados_nueva(ws, header_resumen, encabezados_resumen)

for fila, registro in enumerate(data.get("resumen_general", []), header_resumen + 1):
    valores = [
        obtener(registro, "Banco"),
        obtener(registro, "Cuenta"),
        obtener(registro, "Moneda"),
        obtener(registro, "Fecha_Inicial", "Fecha Inicial"),
        obtener(registro, "Fecha_Final", "Fecha Final"),
        obtener(registro, "Saldo_Inicial", "Saldo Inicial"),
        obtener(registro, "Total_Ingresos", "Total Ingresos"),
        obtener(registro, "Total_Egresos", "Total Egresos"),
        obtener(registro, "Saldo_Final", "Saldo Final")
    ]
    for columna, valor in enumerate(valores, 1):
        escribir(ws, fila, columna, valor)

encabezados_mov = ["Fecha", "No. Referencia", "Descripción", "Moneda", "Ingreso", "Egreso", "Saldo Resultante"]
for banco in data.get("bancos_procesados", []):
    nombre_banco = obtener(banco, "Banco", default="Banco")
    hoja, es_nueva = buscar_hoja_banco(nombre_banco)
    if es_nueva:
        escribir(hoja, 1, 1, "Control Contable")
        celda = editable(hoja, 1, 1)
        if celda is not None:
            celda.font = Font(bold=True, size=14)
    escribir_control(hoja, banco)

    fila_header_mov = fila_con_texto(hoja, ["Fecha", "Descripcion"], 1) or fila_con_texto(hoja, ["Fecha", "No. Referencia"], 1) or 14
    if es_nueva and fila_header_mov == 14:
        encabezados_nueva(hoja, fila_header_mov, encabezados_mov)

    fila_resumen_diario = fila_seccion(hoja, ["resumen diario"], fila_header_mov + 1)
